content.text:
            i += 1
        else:
            return None
    if not (1 <= len(decoded) <= 64):
        return None
    user_canon = ''.join(decoded)

    port_canon = None
    if ':' in hostport:
        host, _, port = hostport.partition(':')
        if not (1 <= len(port) <= 5):
            return None
        for ch in port:
            if ch not in DIGITS:
                return None
        value = int(port)
        if value < 1 or value > 65535:
            return None
        port_canon = str(value)
    else:
        host = hostport

    if not valid_host(host):
        return None

    canon = scheme + ':' + user_canon + '@' + host.lower()
    if port_canon is not None:
        canon += ':' + port_canon
    return canon


def parse_tel_uri(rest):
    """Parse the part after `tel:`; return the canonical URI or None."""
    if not rest.startswith('+'):
        return None
    digits = []
    for ch in rest[1:]:
        if ch in TEL_SEPS:
            continue
        if ch in DIGITS:
            digits.append(ch)
        else:
            return None
    if not (3 <= len(digits) <= 15):
        return None
    if digits[0] == '0':
        return None
    return 'tel:+' + ''.join(digits)


def parse_uri(text):
    """Return the canonical URI string for `text`, or None."""
    if not isinstance(text, str) or not text:
        return None
    low = text.lower()
    if low.startswith('sips:'):
        return parse_sip_uri('sips', text[5:])
    if low.startswith('sip:'):
        return parse_sip_uri('sip', text[4:])
    if low.startswith('tel:'):
        return parse_tel_uri(text[4:])
    return None


def uri_kind(canon):
    if canon.startswith('tel:'):
        return 'tel'
    return 'sip'


